// Generic capture of ApparelMagic's dynamic custom-attribute fields
// (attN_*) -- see adapters/erp/apparelmagic/lib/extractCustomFields.js,
// ported here since Code nodes can't import repo files. Keep in sync if
// that file changes. Skips records with no custom fields set, so the
// am_custom_fields table only ever holds records that actually have data.
function extractCustomFields(record) {
  const fields = {};
  for (const [key, value] of Object.entries(record)) {
    if (/^att\d+/i.test(key) && value != null && value !== '') {
      fields[key] = value;
    }
  }
  return fields;
}

const records = $input.first().json.response || [];
const results = [];
for (const record of records) {
  const fields = extractCustomFields(record);
  if (Object.keys(fields).length === 0) continue;
  results.push({ json: {
    recordType: 'orders',
    recordId: String(record.order_id),
    fields,
  } });
}
return results;

